public class Main {
    static int numSubmatrixSumTarget(int[][] matrix, int target) {
        int rows = matrix.length, cols = matrix[0].length;
        int count = 0;
        for (int top = 0; top < rows; top++) {
            int[] colSum = new int[cols];
            for (int bottom = top; bottom < rows; bottom++) {
                for (int c = 0; c < cols; c++) colSum[c] += matrix[bottom][c];  // collapse into one sum per column

                Map<Integer, Integer> prefixCount = new HashMap<>();
                prefixCount.put(0, 1);
                int s = 0;
                for (int v : colSum) {
                    s += v;
                    count += prefixCount.getOrDefault(s - target, 0);   // Subarray Sum Equals K, applied here
                    prefixCount.merge(s, 1, Integer::sum);
                }
            }
        }
        return count;
    }
}

