#include <bits/stdc++.h>
using namespace std;

int numSubmatrixSumTarget(vector<vector<int>>& matrix, int target) {
    int rows = matrix.size(), cols = matrix[0].size();
    int count = 0;
    for (int top = 0; top < rows; top++) {
        vector<int> colSum(cols, 0);
        for (int bottom = top; bottom < rows; bottom++) {
            for (int c = 0; c < cols; c++) colSum[c] += matrix[bottom][c];   // collapse into one sum per column

            unordered_map<int,int> prefixCount;
            prefixCount[0] = 1;
            int s = 0;
            for (int v : colSum) {
                s += v;
                auto it = prefixCount.find(s - target);
                if (it != prefixCount.end()) count += it->second;     // Subarray Sum Equals K, applied here
                prefixCount[s]++;
            }
        }
    }
    return count;
}
